{
  "name": "@justmpm/ai-tool",
  "version": "6.1.1",
  "description": "Ferramenta de análise de código para projetos TypeScript/JavaScript. Mapa do projeto, impacto de mudanças, Cloud Functions, busca de símbolos e áreas funcionais. Usa Skott + ts-morph internamente.",
  "keywords": [
    "dependency-analysis",
    "impact-analysis",
    "code-analysis",
    "symbol-search",
    "typescript",
    "javascript",
    "skott",
    "ai",
    "claude",
    "opencode"
  ],
  "author": "Koda AI Studio <studio.kodaai@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/anthropic-studio/ai-tool.git"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "ai-tool": "dist/cli.js"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup src/index.ts src/cli.ts --format esm --dts --clean && tsup --config tsup.worker.config.ts",
    "dev": "tsup src/index.ts src/cli.ts --format esm --dts --watch",
    "prepublishOnly": "npm run build",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.25.3",
    "minimatch": "^10.0.1",
    "minisearch": "^7.2.0",
    "parse-git-diff": "^0.0.20",
    "skott": "^0.35.8",
    "stemmer": "^2.0.1",
    "ts-morph": "^27.0.2",
    "zod": "^3.25.76"
  },
  "devDependencies": {
    "@types/node": "^22.15.21",
    "tsup": "^8.5.0",
    "tsx": "^4.19.0",
    "typescript": "^5.8.3",
    "vitest": "^4.1.0"
  },
  "overrides": {
    "effect": "3.20.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
